-- Diferencias de estructura (solo lectura). Muestra SOLO lo raro:
--  * funciones con nombre que ninguna migración crea, o con varias versiones (sobrecargas)
--  * funciones que las migraciones crean y aquí no existen
--  * índices sueltos (no de llaves) que ninguna migración crea, o que faltan
--  * configuración del bucket de fotos y sus políticas
WITH esperadas_fn(n) AS (SELECT unnest(ARRAY['adjust_account_balance','apply_loan_stock','award_loyalty_points','cancel_pos_sale','charge_account_gmf','charge_lent_loan','close_borrowed_loan','create_lent_loan','create_order_with_items','create_pos_sale','decrement_stock','decrement_variant_stock','delete_customer_credit','delete_loan','delete_operating_expense','delete_supplier_invoice','edit_pos_sale','generate_order_number','get_user_role','next_addi_release_date','next_business_day_co','pay_customer_credit','pay_supplier_invoice','prevent_role_self_escalation','queue_product_restock_notification','queue_variant_restock_notification','record_operating_expense','redeem_loyalty_points','redeem_loyalty_points_for_coupon','release_addi_pending','release_card_pending','release_sistecredito_pending','reopen_loans_on_sale_cancel','restore_stock_for_cancelled_order','sell_borrowed_loan','set_loan_status','set_review_verified_purchase','sync_product_stock_from_variants','transfer_between_accounts','update_updated_at_column'])),
     esperados_ix(n) AS (SELECT unnest(ARRAY['idx_abandoned_carts_pending','idx_account_movements_account','idx_account_movements_created_at','idx_account_movements_reference','idx_account_receivables_account','idx_addi_pending_account','idx_addi_pending_release_date','idx_audit_logs_actor','idx_audit_logs_created_at','idx_audit_logs_record','idx_audit_logs_table','idx_card_pending_account','idx_card_pending_release_date','idx_coupons_user_id','idx_customer_credit_payments_credit','idx_customer_credits_status','idx_daily_closures_date','idx_daily_notes_date','idx_inventory_created_at','idx_inventory_movements_created_at','idx_inventory_movements_product','idx_inventory_movements_variant','idx_inventory_product','idx_loans_direction','idx_loans_product','idx_loans_sale_order','idx_loans_status','idx_loyalty_ledger_order_earn','idx_loyalty_ledger_user_id','idx_notes_completed','idx_notes_due_date','idx_operating_expenses_category','idx_operating_expenses_date','idx_operating_expenses_gmf_source','idx_operating_expenses_parent','idx_order_items_order','idx_order_items_product','idx_order_items_variant','idx_orders_channel','idx_orders_created_at','idx_orders_order_number','idx_orders_payment_status','idx_orders_seller_id','idx_orders_status','idx_orders_user','idx_payments_account','idx_payments_order','idx_payments_provider','idx_payments_status','idx_processed_webhooks_created_at','idx_product_variants_active','idx_product_variants_barcode','idx_product_variants_product','idx_products_active','idx_products_barcode','idx_products_category','idx_products_deleted_at','idx_products_featured','idx_products_slug','idx_restock_email','idx_restock_notified','idx_restock_product','idx_restock_queue_pending','idx_restock_variant','idx_reviews_approved','idx_reviews_product','idx_reviews_user','idx_sistecredito_pending_account','idx_sistecredito_pending_release_date','idx_supplier_invoice_items_invoice','idx_supplier_invoice_payments_invoice','idx_supplier_invoices_due_date','idx_supplier_invoices_status','idx_wishlists_product','idx_wishlists_user','products_barcode_active_key','products_sku_active_key','products_slug_active_key','restock_subscriptions_product_email_no_variant_key','restock_subscriptions_product_variant_email_key'])),
     fn AS (SELECT p.proname AS n, pg_get_function_identity_arguments(p.oid) AS args
            FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public'),
     ix AS (SELECT i.indexname AS n, i.tablename AS t FROM pg_indexes i
            WHERE i.schemaname = 'public'
              AND NOT EXISTS (SELECT 1 FROM pg_constraint c JOIN pg_class k ON k.oid = c.conindid WHERE k.relname = i.indexname))
SELECT 'funcion no esperada' AS tipo, n || '(' || args || ')' AS detalle FROM fn WHERE n NOT IN (SELECT n FROM esperadas_fn)
UNION ALL SELECT 'funcion con ' || count(*) || ' versiones', n || ': ' || string_agg('(' || args || ')', ' | ') FROM fn GROUP BY n HAVING count(*) > 1
UNION ALL SELECT 'funcion de migracion que no esta', n FROM esperadas_fn WHERE n NOT IN (SELECT n FROM fn)
UNION ALL SELECT 'indice no esperado', t || '.' || n FROM ix WHERE n NOT IN (SELECT n FROM esperados_ix)
UNION ALL SELECT 'indice de migracion que no esta', n FROM esperados_ix WHERE n NOT IN (SELECT indexname FROM pg_indexes WHERE schemaname = 'public')
UNION ALL SELECT 'bucket', id || ' publico=' || public || ' limite=' || coalesce(file_size_limit::text, '-') || ' tipos=' || coalesce(array_to_string(allowed_mime_types, ','), '-') FROM storage.buckets
UNION ALL SELECT 'politica de storage', policyname FROM pg_policies WHERE schemaname = 'storage'
ORDER BY 1, 2;
